@startuml
skinparam classAttributeIconSize 0
skinparam classBackgroundColor #f8fafc
skinparam classBorderColor #475569

class Employee {
  {field} + ssn : char(9) {PK}
  {field} + first_names [1..*] : varchar(30)
  {field} + last_name : varchar(30)
  {field} + birth_date : date
  {field} + gender : char(1)
  {field} + salary : decimal(10,2)
  {field} + address : AddressType
  {field} / age : integer {derived}
}

class AddressType <<composite>> {
  + street_number : varchar(10)
  + street_name : varchar(50)
  + city : varchar(30)
  + postal_code : varchar(10)
}

Employee *-- AddressType
@enduml

flowchart LR
  Emp["EMPLOYEE\nssn {PK}\nname\nsalary"]
  Rel{"Supervises"}

  Emp -->|"0..1\n[supervisor]"| Rel
  Rel -->|"0..*\n[supervisee]"| Emp

  classDef ent fill:#ede9fe,stroke:#6366f1,stroke-width:2px;
  classDef rel fill:#fef3c7,stroke:#d97706,stroke-width:1.5px;
  class Emp ent;
  class Rel rel;

flowchart LR
  Emp["EMPLOYEE (Owner / Strong)\nssn {PK}\nname"]
  Dep["DEPENDENT (Weak Entity)\ndependent_name {Partial Key}\nbirth_date\nrelationship"]
  Rel{"Has_Dependent\n(Identifying Rel)"}

  Emp ---|"1..1"| Rel
  Rel ---|"0..*"| Dep

  classDef strong fill:#f0f9ff,stroke:#0284c7,stroke-width:2px;
  classDef weak fill:#fdf2f8,stroke:#db2777,stroke-width:2px,stroke-dasharray: 5 5;
  classDef idrel fill:#fef3c7,stroke:#d97706,stroke-width:1.5px;
  class Emp strong;
  class Dep weak;
  class Rel idrel;

@startuml
skinparam classAttributeIconSize 0
skinparam classBackgroundColor #f8fafc
skinparam classBorderColor #475569

abstract class Employee {
  + ssn : char(9) {PK}
  + name : varchar(50)
  + birth_date : date
}

class SalariedEmployee {
  + annual_salary : decimal(10,2)
}

class HourlyEmployee {
  + hourly_rate : decimal(6,2)
}

class Engineer {
  + engineering_discipline : varchar(30)
}

class Manager {
  + bonus_budget : decimal(10,2)
}

Employee <|-- SalariedEmployee : "{disjoint, total}"
Employee <|-- HourlyEmployee : "{disjoint, total}"
Employee <|-- Engineer : "{overlapping, partial}"
Employee <|-- Manager : "{overlapping, partial}"
@enduml
